import React from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  LinearProgress,
  List,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Typography,
} from '@mui/material';
import {
  CheckCircle as CheckCircleIcon,
  RadioButtonUnchecked as UncheckedIcon,
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import type { OnboardingProgress } from '../../utils/sustainabilityUx';
import { MSME_SIMPLIFIED_SECTION_TITLE } from '../../constants/msmeSimplifiedUi';

export interface DashboardOnboardingChecklistProps {
  progress: OnboardingProgress;
}

export const DashboardOnboardingChecklist: React.FC<DashboardOnboardingChecklistProps> = ({ progress }) => {
  const navigate = useNavigate();

  if (progress.allComplete) {
    return null;
  }

  const nextStep = progress.steps.find((step) => !step.complete);

  return (
    <Card
      variant="outlined"
      sx={{
        mb: 3,
        borderColor: 'primary.main',
        bgcolor: (theme) =>
          theme.palette.mode === 'dark' ? 'rgba(27, 94, 32, 0.1)' : 'rgba(27, 94, 32, 0.03)',
      }}
    >
      <CardContent>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 2, mb: 2 }}>
          <Box>
            <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
              {MSME_SIMPLIFIED_SECTION_TITLE}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              {progress.completedCount} of {progress.totalCount} steps done — about{' '}
              {progress.steps
                .filter((step) => !step.complete)
                .reduce((sum, step) => sum + (step.estimatedMinutes ?? 0), 0)}{' '}
              minutes left
            </Typography>
          </Box>
          <Typography variant="h6" sx={{ fontWeight: 800, color: 'primary.main' }}>
            {progress.percent}%
          </Typography>
        </Box>
        <LinearProgress
          variant="determinate"
          value={progress.percent}
          sx={{ height: 8, borderRadius: 1, mb: 2 }}
        />
        {nextStep ? (
          <Box sx={{ mb: 2, p: 1.5, borderRadius: 1, bgcolor: 'action.hover' }}>
            <Typography variant="overline" color="primary" sx={{ fontWeight: 700 }}>
              Up next
            </Typography>
            <Typography variant="body1" sx={{ fontWeight: 700, mb: 0.25 }}>
              {nextStep.label}
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
              {nextStep.description}
            </Typography>
            <Button variant="contained" size="small" onClick={() => navigate(nextStep.path)}>
              {nextStep.estimatedMinutes ? `Start (~${nextStep.estimatedMinutes} min)` : 'Start this step'}
            </Button>
          </Box>
        ) : null}
        <List dense disablePadding>
          {progress.steps.map((step) => (
            <ListItem key={step.id} disablePadding>
              <ListItemButton onClick={() => navigate(step.path)} sx={{ borderRadius: 1 }}>
                <ListItemIcon sx={{ minWidth: 36 }}>
                  {step.complete ? (
                    <CheckCircleIcon color="success" fontSize="small" />
                  ) : (
                    <UncheckedIcon color="disabled" fontSize="small" />
                  )}
                </ListItemIcon>
                <ListItemText
                  primary={
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                      <Typography
                        component="span"
                        variant="body2"
                        sx={{ fontWeight: step.complete ? 500 : 600 }}
                      >
                        {step.label}
                      </Typography>
                      {step.estimatedMinutes && !step.complete ? (
                        <Chip size="small" label={`~${step.estimatedMinutes} min`} variant="outlined" />
                      ) : null}
                    </Box>
                  }
                  secondary={step.description}
                />
              </ListItemButton>
            </ListItem>
          ))}
        </List>
      </CardContent>
    </Card>
  );
};
